36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "title")
40	    private String title;
41	
42	    @Column(name = "address_line1")
43	    private String addressLine1;
44	
45	    @Column(name = "address_line2")
46	    private String addressLine2;
47	
48	    @Column(name = "address")
49	    @NotEmpty
50	    private String address;
51	
52	    @Column(name = "city")
53	    @NotEmpty
54	    private String city;
55	
56	    @Column(name = "postcode")
57	    private String postcode;
58	
59	    @Column(name = "telephone")
60	    @NotEmpty
61	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
62	    private String telephone;
63	
64	    @Column(name = "email")
65	    @Email
66	    private String email;
67	
68	    @Column(name = "registration_date", columnDefinition = "DATE")
69	    private LocalDate registrationDate;
70	
71	    @Column(name = "birth_date", columnDefinition = "DATE")
