228	    protected Set<Pet> getPetsInternal() {
229	        if (this.pets == null) {
230	            this.pets = new HashSet<>();
231	        }
232	        return this.pets;
233	    }
234	
235	    protected void setPetsInternal(Set<Pet> pets) {
236	        this.pets = pets;
237	    }
238	
239	    public List<Pet> getPets() {
240	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
241	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
242	        return Collections.unmodifiableList(sortedPets);
243	    }
244	
245	    public void setPets(List<Pet> pets) {
246	        this.pets = new HashSet<>(pets);
247	    }
248	
249	    public void addPet(Pet pet) {
250	        getPetsInternal().add(pet);
251	        pet.setOwner(this);
252	    }
253	
254	    /**
255	     * Return the Pet with the given name, or null if none found for this Owner.
256	     *
257	     * @param name to test
258	     * @return true if pet name is already in use
259	     */
260	    public Pet getPet(String name) {
261	        return getPet(name, false);
262	    }
263	
264	    /**
265	     * Return the Pet with the given name, or null if none found for this Owner.
266	     *
267	     * @param name to test
268	     * @return true if pet name is already in use
269	     */
270	    public Pet getPet(String name, boolean ignoreNew) {
271	        name = name.toLowerCase();
272	        for (Pet pet : getPetsInternal()) {
273	            if (!ignoreNew || !pet.isNew()) {
274	                String compName = pet.getName();
275	                compName = compName.toLowerCase();
276	                if (compName.equals(name)) {
277	                    return pet;
278	                }
279	            }
280	        }
281	        return null;
282	    }
283	
284	    public Pet getPet(Integer petId) {
285	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
286	    }
287	
288	    @Override
289	    public String toString() {
290	        return new ToStringCreator(this)
291	
292	            .append("id", this.getId())
293	            .append("new", this.isNew())
294	            .append("lastName", this.getLastName())
295	            .append("firstName", this.getFirstName())
296	            .append("title", this.title)
297	            .append("addressLine1", this.addressLine1)
298	            .append("addressLine2", this.addressLine2)
299	            .append("address", this.address)
300	            .append("city", this.city)
301	            .append("postcode", this.postcode)
302	            .append("telephone", this.telephone)
303	            .append("email", this.email)
304	            .append("registrationDate", this.registrationDate)
305	            .append("birthDate", this.birthDate)
306	            .append("customerCode", this.customerCode)
307	            .append("householdId", this.householdId)
308	            .append("namesakeCount", this.namesakeCount)
309	            .append("householdMemberCount", this.householdMemberCount)
310	            .append("possibleDuplicate", this.possibleDuplicate)
311	            .append("possibleDuplicateOf", this.possibleDuplicateOf)
312	            .toString();
313	    }
314	}
