1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Flags the new owner as a possible duplicate of an existing one. A <em>possible</em> duplicate
10	 * shares an existing owner's household (same last name and postcode) but was given a different
11	 * telephone (see {@link PossibleDuplicates}). The matching owner's id is recorded so the
12	 * response can point at it; otherwise the owner is flagged as no duplicate.
13	 *
14	 * <p>An owner that declared {@code sharesHousehold} is a <em>declared</em> household member, not
15	 * a suspected duplicate, so it is never flagged even though it shares the household.
16	 */
17	public class DetectPossibleDuplicate {
18	
19	    public void service(@Val Owner owner, @Val OwnerFieldsDto request,
20	            OwnerRepository ownerRepository) {
21	        Integer matchId = Boolean.TRUE.equals(request.getSharesHousehold()) ? null
22	                : PossibleDuplicates.matchFor(owner, ownerRepository).orElse(null);
23	        owner.setPossibleDuplicate(matchId != null);
24	        owner.setPossibleDuplicateOf(matchId);
25	    }
26	}
