1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
6	import tools.jackson.databind.node.ObjectNode;
7	
8	/** exclude-deleted: DELETE /api/owners/{id} soft-deletes (flags 'deleted' true, retains the
9	 * record); the create endpoint's duplicate/identity checks then ignore deleted owners. */
10	class AcceptanceTest extends AcceptanceBase {
11	
12		@Test
13		void coreSoftDeleteFlagsAndRetains() throws Exception {
14			int id = createOwnerOk(structuredOwner());
15			getOwner(id).andExpect(status().isOk()).andExpect(jsonPath("$.deleted").value(false));
16			deleteOwner(id);
17			getOwner(id).andExpect(status().isOk()).andExpect(jsonPath("$.deleted").value(true));
18		}
19	
20		@Test
21		void coreDeletedOwnerIgnoredByDuplicateCheck() throws Exception {
22			ObjectNode a = structuredOwner();
23			int id = createOwnerOk(a);
24			deleteOwner(id); // A is soft-deleted
25			createOwner(a.deepCopy()).andExpect(status().is2xxSuccessful()); // only match is deleted -> allowed
26		}
27	}
