package org.springframework.samples.petclinic.repository;

import java.util.Collection;

import org.springframework.dao.DataAccessException;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.samples.petclinic.model.BaseEntity;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Repository class for <code>Owner</code> domain objects All method names are compliant with Spring Data naming
 * conventions so this interface can easily be extended for Spring Data See here: http://static.springsource.org/spring-data/jpa/docs/current/reference/html/jpa.repositories.html#jpa.query-methods.query-creation
 *
 * @author Ken Krebs
 * @author Juergen Hoeller
 * @author Sam Brannen
 * @author Michael Isvy
 * @author Vitaliy Fedoriv
 */
public interface OwnerRepository {

    /**
     * Retrieve <code>Owner</code>s from the data store by last name, returning all owners whose last name <i>starts</i>
     * with the given name.
     *
     * @param lastName Value to search for
     * @return a <code>Collection</code> of matching <code>Owner</code>s (or an empty <code>Collection</code> if none
     * found)
     */
    Collection<Owner> findByLastName(String lastName) throws DataAccessException;

    Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException;

    /**
     * Retrieve an <code>Owner</code> from the data store by id.
     *
     * @param id the id to search for
     * @return the <code>Owner</code> if found
     * @throws org.springframework.dao.DataRetrievalFailureException if not found
     */
    Owner findById(int id) throws DataAccessException;


    /**
     * Save an <code>Owner</code> to the data store, either inserting or updating it.
     *
     * @param owner the <code>Owner</code> to save
     * @see BaseEntity#isNew
     */
    void save(Owner owner) throws DataAccessException;

    /**
     * Retrieve <code>Owner</code>s from the data store, returning all owners 
     *
     * @return a <code>Collection</code> of <code>Owner</code>s (or an empty <code>Collection</code> if none
     * found)
     */
	Collection<Owner> findAll() throws DataAccessException;

    Page<Owner> findAll(Pageable pageable) throws DataAccessException;

    /**
     * Count the total number of <code>Owner</code>s in the data store.
     *
     * @return the number of owners
     */
    int count() throws DataAccessException;

    /**
     * Delete an <code>Owner</code> to the data store by <code>Owner</code>.
     *
     * @param owner the <code>Owner</code> to delete
     * 
     */
	void delete(Owner owner) throws DataAccessException;


}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * The duplicate block: rejects a create request whose {@link Households#id(OwnerFieldsDto)
 * household id} — its last name and postcode — matches an existing owner's, because owners in
 * the same household are otherwise indistinguishable at registration. A request may opt out by
 * setting {@code sharesHousehold}, declaring it a genuine second member of that household; that
 * only bypasses this block, since the household link itself is assigned deterministically
 * later (see {@link AssignHousehold}).
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws HouseholdDuplicateException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String householdId = Households.id(request);
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(Households.id(existing))) {
                throw new HouseholdDuplicateException(householdId);
            }
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Optional;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Soft duplicate matching: a new owner is a <em>possible</em> duplicate of an existing owner
 * when they belong to the same {@link Households household} (same last name and postcode) yet
 * were given a different telephone number.
 *
 * <p>Unlike a household duplicate (see {@link EnsureUniqueHousehold}), which is rejected
 * outright, a possible duplicate that reaches this point has declared {@code sharesHousehold};
 * it is still created and merely flagged with the id of the owner it resembles. The differing
 * telephone is what distinguishes it from an exact re-registration.
 */
final class PossibleDuplicates {

    private PossibleDuplicates() {
    }

    /**
     * The id of the earliest existing owner the given owner possibly duplicates — same
     * household, different telephone — or empty when there is no such owner.
     */
    static Optional<Integer> matchFor(Owner owner, OwnerRepository ownerRepository) {
        Owner match = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (matches(owner, existing) && (match == null || existing.getId() < match.getId())) {
                match = existing;
            }
        }
        return Optional.ofNullable(match).map(Owner::getId);
    }

    private static boolean matches(Owner owner, Owner existing) {
        return Households.sameHousehold(owner, existing)
                && !sameTelephone(owner.getTelephone(), existing.getTelephone());
    }

    private static boolean sameTelephone(String a, String b) {
        return a != null && a.equals(b);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many existing owners already share the new owner's name. Counts the owners
 * matching on first and last name (see {@link Namesakes#matches}) before the new owner is
 * saved, so the count reflects the state just prior to this create.
 */
public class CountNamesakes {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (Namesakes.matches(existing, owner.getFirstName(), owner.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many owners share the new owner's household. Counts the existing owners with
 * the same {@code householdId} (assigned earlier by {@link AssignHousehold} from last name and
 * postcode) and adds one for the owner being created, so the count reflects the household size
 * that results from this create. An owner whose last name and postcode match no one else is a
 * household of one.
 */
public class CountHouseholdMembers {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int count = 1;
        for (Owner existing : ownerRepository.findAll()) {
            if (Households.sameHousehold(owner, existing)) {
                count++;
            }
        }
        owner.setHouseholdMemberCount(count);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.CityRegion;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns a new owner's customer code before it is saved. The code is {@code <REGION>-<HASH8>}
 * (see {@link CustomerCode}): the region derived from the owner's postcode plus a hash of the
 * owner's normalized telephone and last name. Runs after the telephone has been normalized, so
 * {@link Owner#getTelephone()} already holds the canonical form the hash is taken over. Should
 * that code collide with an existing owner's, it is de-duplicated with a {@code -<n>} suffix.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String region = CityRegion.localityOf(owner.getPostcode(), owner.getCity());
        String code = CustomerCode.format(region, owner.getTelephone(), owner.getLastName());
        Set<String> taken = new HashSet<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getCustomerCode() != null) {
                taken.add(existing.getCustomerCode());
            }
        }
        owner.setCustomerCode(CustomerCode.deduplicate(code, taken));
    }
}

